INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1388908, 178291, 22533, '<td valign="top">Go Joe! Sorry, had to say it. (Probably along with everyone else)</td>', 'Go Joe! Sorry, had to say it. (Probably along with everyone else)', '2005-05-16 13:52:56.000000', NULL, 1),
(1388915, 178335, 22533, '<td valign="top">Great focus.</td>', 'Great focus.', '2005-05-16 13:54:43.000000', NULL, 1),
(1388930, 177951, 34247, '<td valign="top">there''s a bit of framing on the top and right, but not on the right. Am not sure you meant to do that, or if that was accidentally created during crop. won''t effect my rating of the image, but just a note on it.</td>', 'there''s a bit of framing on the top and right, but not on the right. Am not sure you meant to do that, or if that was accidentally created during crop. won''t effect my rating of the image, but just a note on it.', '2005-05-16 13:59:57.000000', NULL, 1),
(1388934, 177503, 2764, '<td valign="top">oooh gorgeous!  there is a slight tilt to the right, i think.  you''d be surprised how a bit of tilt can influence a viewer.  it is unsettling and even if it goes unnoticed thes is an uneasy impression that something is "wrong".  Do you know the measure tool trick in photoshop?  Its under the eyedropper - draw a line along a visual that should appear straight (here the center tower and its reflection) then choose rotate canvas arbitrary.  If i rotate our tower .32 degrees clockwise it looks better to me.</td>', 'oooh gorgeous!  there is a slight tilt to the right, i think.  you''d be surprised how a bit of tilt can influence a viewer.  it is unsettling and even if it goes unnoticed thes is an uneasy impression that something is "wrong".  Do you know the measure tool trick in photoshop?  Its under the eyedropper - draw a line along a visual that should appear straight (here the center tower and its reflection) then choose rotate canvas arbitrary.  If i rotate our tower .32 degrees clockwise it looks better to me.', '2005-05-16 14:01:30.000000', NULL, 1),
(1388935, 177618, 34247, '<td valign="top">I think the idea here is outstanding and will rate the image 8 based on that and the color tones. Had the focus on the people been sharper and the lighting difference been greater between the silhouetted forms and the brighter background, this would have rated higher with me.</td>', 'I think the idea here is outstanding and will rate the image 8 based on that and the color tones. Had the focus on the people been sharper and the lighting difference been greater between the silhouetted forms and the brighter background, this would have rated higher with me.', '2005-05-16 14:01:41.000000', NULL, 1),
(1388941, 177975, 2764, '<td valign="top">odd color choice - it''s different - nice composition<br/></td>', 'odd color choice - it''s different - nice composition', '2005-05-16 14:03:33.000000', NULL, 1),
