(1392226, 178149, 32378, '<td valign="top">This picture appears to be underexosed.</td>', 'This picture appears to be underexosed.', '2005-05-17 17:22:13.000000', NULL, 1),
(1392228, 178562, 35645, '<td valign="top">Love the detail and texture on the water, and I like the composition. This seems to have a purple cast over the whole image that just doesn''t look natural.</td>', 'Love the detail and texture on the water, and I like the composition. This seems to have a purple cast over the whole image that just doesn''t look natural.', '2005-05-17 17:22:57.000000', NULL, 1),
