(1401812, 177956, 34759, '<td valign="top">Absolutely beautiful.</td>', 'Absolutely beautiful.', '2005-05-20 23:41:23.000000', NULL, 1),
(1401813, 177978, 34759, '<td valign="top">It would have been better if you had cropped the top a bit lower to get rid of the black in the upper left corner. Also the screen is a bit distracting.</td>', 'It would have been better if you had cropped the top a bit lower to get rid of the black in the upper left corner. Also the screen is a bit distracting.', '2005-05-20 23:42:39.000000', NULL, 1),
(1401814, 178255, 34759, '<td valign="top">Very nice. The clouds look great and the water looks so calm!</td>', 'Very nice. The clouds look great and the water looks so calm!', '2005-05-20 23:43:00.000000', NULL, 1),
