(1402721, 177703, 34759, '<td valign="top">Gorgeous shot! I love all the different textures in the water.</td>', 'Gorgeous shot! I love all the different textures in the water.', '2005-05-21 18:12:31.000000', NULL, 1),
(1402726, 177108, 34759, '<td valign="top">The branch in the upper left section is somewhat distracting, but a very pretty shot none the less.</td>', 'The branch in the upper left section is somewhat distracting, but a very pretty shot none the less.', '2005-05-21 18:15:32.000000', NULL, 1),
(1402727, 178196, 1024, '<td valign="top">The power in this photograph is in its simplicity.  Wonderful tones and great background.</td>', 'The power in this photograph is in its simplicity.  Wonderful tones and great background.', '2005-05-21 18:15:56.000000', NULL, 1),
(1402728, 178530, 1024, '<td valign="top">Although technically this IS a silhouette, I tend to look for sharp edges and defined shapes.  Thisis just my personal opinion though.  Good luck.</td>', 'Although technically this IS a silhouette, I tend to look for sharp edges and defined shapes.  Thisis just my personal opinion though.  Good luck.', '2005-05-21 18:17:07.000000', NULL, 1),
(1402731, 178293, 1024, '<td valign="top">A true sillhouette will have no features visible within the blackness.  This is a very nice photo, but maybe not for this challenge.</td>', 'A true sillhouette will have no features visible within the blackness.  This is a very nice photo, but maybe not for this challenge.', '2005-05-21 18:18:04.000000', NULL, 1),
(1402733, 177263, 1024, '<td valign="top">Beautiful colors and 2 very striking sillouettes.</td>', 'Beautiful colors and 2 very striking sillouettes.', '2005-05-21 18:18:50.000000', NULL, 1),
(1402735, 178576, 1024, '<td valign="top">This is incredible.  Very strong sillhouette against a stunning background.</td>', 'This is incredible.  Very strong sillhouette against a stunning background.', '2005-05-21 18:19:30.000000', NULL, 1),
(1402738, 178004, 1024, '<td valign="top">There is much humor in this silljouette.  I love the way the birds are in different flying positions.</td>', 'There is much humor in this silljouette.  I love the way the birds are in different flying positions.', '2005-05-21 18:20:35.000000', NULL, 1),
(1402739, 177924, 34759, '<td valign="top">Beautiful shot! I love the sky.</td>', 'Beautiful shot! I love the sky.', '2005-05-21 18:21:25.000000', NULL, 1),
(1402742, 178393, 1024, '<td valign="top">The bird silhouette is a little soft, not sure if that is from a slow shutter speed or camera shake.  A tripod and highter ISO might have helped a bit</td>', 'The bird silhouette is a little soft, not sure if that is from a slow shutter speed or camera shake.  A tripod and highter ISO might have helped a bit', '2005-05-21 18:22:11.000000', NULL, 1);
